import React, { useState, useCallback } from 'react';
import { useDropzone } from 'react-dropzone';
import { XMLParser } from 'fast-xml-parser';
import { Upload, FileText, AlertCircle, List } from 'lucide-react';
import './App.css';

// --- 1. CONFIGURATION: MAP YOUR CODES HERE ---
// You can add, remove, or rename these codes (E001, C001) to match your exact spec.
const FIELD_MAPPINGS = {
  'pacs.008': [
    { code: 'H001', label: 'Message ID',        path: 'GrpHdr.MsgId' },
    { code: 'H002', label: 'Creation Date',     path: 'GrpHdr.CreDtTm' },
    { code: 'H003', label: 'Nb of Tx',          path: 'GrpHdr.NbOfTxs' },
    { code: 'E001', label: 'End-to-End ID',     path: 'CdtTrfTxInf.PmtId.EndToEndId' },
    { code: 'C001', label: 'Amount',            path: 'CdtTrfTxInf.IntrBkSttlmAmt' },
    { code: 'C002', label: 'Currency',          path: 'CdtTrfTxInf.IntrBkSttlmAmt.@_Ccy' },
    { code: 'T001', label: 'Settlement Date',   path: 'CdtTrfTxInf.IntrBkSttlmDt' },
    { code: 'D001', label: 'Debtor IBAN',       path: 'CdtTrfTxInf.DbtrAcct.Id.IBAN' },
    { code: 'D002', label: 'Creditor IBAN',     path: 'CdtTrfTxInf.CdtrAcct.Id.IBAN' },
    { code: 'R001', label: 'Remittance Info',   path: 'CdtTrfTxInf.RmtInf.Ustrd' }
  ],
  'pacs.002': [
    { code: 'H001', label: 'Message ID',        path: 'GrpHdr.MsgId' },
    { code: 'S001', label: 'Original Msg ID',   path: 'OrgnlGrpInfAndSts.OrgnlMsgId' },
    { code: 'S002', label: 'Group Status',      path: 'OrgnlGrpInfAndSts.GrpSts' },
    { code: 'T002', label: 'Reason Code',       path: 'TxInfAndSts.StsRsnInf.Rsn.Cd' },
    { code: 'T003', label: 'Addtl Info',        path: 'TxInfAndSts.StsRsnInf.AddtlInf' }
  ]
};

function App() {
  const [xmlContent, setXmlContent] = useState('');
  const [parsedResult, setParsedResult] = useState(null);
  const [error, setError] = useState(null);

  const parser = new XMLParser({
    ignoreAttributes: false,
    attributeNamePrefix: "@_", 
    removeNsp: true 
  });

  // --- HELPER 1: Find the Root Tag (Handling the 'F1...' vs 'FI...' issue) ---
  const findRootByCandidates = (obj, candidates) => {
    if (!obj || typeof obj !== 'object') return null;
    for (const key of Object.keys(obj)) {
        // Case insensitive matching for tag names
        if (candidates.some(c => c.toLowerCase() === key.toLowerCase())) return obj[key];
    }
    for (const key in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        const found = findRootByCandidates(obj[key], candidates);
        if (found) return found;
      }
    }
    return null;
  };

  // --- HELPER 2: Extract Value using the Dot Path (e.g. "GrpHdr.MsgId") ---
  const extractValueByPath = (rootObj, path) => {
    try {
      const keys = path.split('.');
      let current = rootObj;

      for (const key of keys) {
        if (!current) return 'MISSING';

        // Handle Arrays (Always take the first transaction [0] for validation)
        if (Array.isArray(current)) current = current[0];

        // Case Insensitive Key Lookup
        const foundKey = Object.keys(current).find(k => k.toLowerCase() === key.toLowerCase());

        if (foundKey) {
          current = current[foundKey];
        } else {
          return 'MISSING';
        }
      }
      // If object (like Amount with currency attribute), extract text value if exists
      if (typeof current === 'object' && current['#text']) return current['#text'];
      if (typeof current === 'object' && !current['#text']) return JSON.stringify(current).substring(0, 20) + '...';

      return current;
    } catch (e) {
      return 'ERROR';
    }
  };

  const processXML = (xmlString) => {
    try {
      setError(null);
      setParsedResult(null);
      const jsonObj = parser.parse(xmlString);

      let type = 'Unknown';
      let isValid = false;
      let extractedData = [];
      let validationMessage = '';

      // 1. Define Candidates
      const pacs008Roots = ['FIToFICustomerCreditTransfer', 'FIToFICstmrCdtTrf', 'F1ToFICstmerCdtTrf'];
      const pacs002Roots = ['FIToFIPaymentStatusReport', 'FIToFIPmtStsRpt'];

      // 2. Find Roots
      const sctInstRoot = findRootByCandidates(jsonObj, pacs008Roots);
      const statusRoot = findRootByCandidates(jsonObj, pacs002Roots);

      let activeRoot = null;
      let mappingKey = null;

      if (sctInstRoot) {
        type = 'pacs.008 (SCT Inst)';
        activeRoot = sctInstRoot;
        mappingKey = 'pacs.008';
        isValid = true;
      } else if (statusRoot) {
        type = 'pacs.002 (Status Report)';
        activeRoot = statusRoot;
        mappingKey = 'pacs.002';
        isValid = true;
      }

      // 3. Extract Data based on Mappings
      if (isValid && activeRoot) {
        validationMessage = "Valid Structure Found";

        // Loop through the configuration to build the result
        extractedData = FIELD_MAPPINGS[mappingKey].map(field => ({
           code: field.code,
           label: field.label,
           value: extractValueByPath(activeRoot, field.path),
           path: field.path
        }));

      } else {
         validationMessage = "Could not find standard SCT Inst root tags.";
      }

      setParsedResult({ type, isValid, message: validationMessage, data: extractedData });

    } catch (err) {
      setError("XML Syntax Error: " + err.message);
    }
  };

  const onDrop = useCallback((acceptedFiles) => {
    const file = acceptedFiles[0];
    const reader = new FileReader();
    reader.onload = () => {
        setXmlContent(reader.result);
        processXML(reader.result);
    };
    reader.readAsText(file);
  }, []);

  const { getRootProps, getInputProps } = useDropzone({ onDrop });

  return (
    <div className="container">
      <div className="header"><h1>SCT Inst Validator</h1></div>

      <div className="input-methods">
        <div className="card">
            <div {...getRootProps({ className: 'dropzone' })}>
                <input {...getInputProps()} />
                <p>Drag & drop XML file</p>
            </div>
        </div>
        <div className="card">
            <textarea value={xmlContent} onChange={(e) => setXmlContent(e.target.value)} placeholder="Paste XML..." />
            <button className="btn" onClick={() => processXML(xmlContent)}>Validate</button>
        </div>
      </div>

      {error && <div className="card" style={{color: 'red'}}><AlertCircle size={20}/> {error}</div>}

      {parsedResult && !error && (
        <div className="results-area card">
            <div style={{display: 'flex', justifyContent: 'space-between'}}>
                <h2>Analysis Results</h2>
                <span className={`badge ${parsedResult.isValid ? 'badge-success' : 'badge-error'}`}>
                    {parsedResult.isValid ? 'VALID' : 'INVALID'}
                </span>
            </div>
            <p>{parsedResult.message}</p>

            {parsedResult.data.length > 0 && (
                <table>
                    <thead>
                        <tr>
                            <th style={{width: '80px'}}>Code</th>
                            <th>Element Name</th>
                            <th>Value</th>
                        </tr>
                    </thead>
                    <tbody>
                        {parsedResult.data.map((r, i) => (
                            <tr key={i}>
                                <td><span className="badge badge-info" style={{fontSize:'0.9em'}}>{r.code}</span></td>
                                <td>
                                    {r.label}<br/>
                                    <small style={{color:'#888', fontSize:'0.7em'}}>{r.path}</small>
                                </td>
                                <td>
                                    {r.value === 'MISSING' 
                                        ? <span style={{color: '#ff9800', fontWeight:'bold'}}>MISSING</span> 
                                        : <code style={{color: '#28a745', fontWeight:'bold'}}>{r.value}</code>
                                    }
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            )}
        </div>
      )}
    </div>
  );
}

export default App;
